BEGIN; SET LOCAL statement_timeout='5s'; SET LOCAL lock_timeout='500ms';
    SELECT set_config('p06.review_owned',count(*)::text,true) FROM (
      SELECT run.id FROM p06_r3_members_f91627529a584d2398b195599b1adb86.runs run JOIN p06_r3_members_f91627529a584d2398b195599b1adb86.links link
      ON link.company=run.company AND link.run=run.id
      WHERE link.company=1 AND link.root=1 ORDER BY run.id FOR UPDATE OF run NOWAIT) owned;
    SELECT pg_sleep(2);
    INSERT INTO p06_r3_members_f91627529a584d2398b195599b1adb86.history SELECT usage.* FROM p06_r3_members_f91627529a584d2398b195599b1adb86.usage usage JOIN p06_r3_members_f91627529a584d2398b195599b1adb86.links link
      ON link.company=usage.company AND link.run=usage.run WHERE link.company=1 AND link.root=1;
    DO $$ DECLARE removed bigint; BEGIN
      WITH retained AS MATERIALIZED(SELECT company,run FROM p06_r3_members_f91627529a584d2398b195599b1adb86.links WHERE company=1 AND root=1)
      DELETE FROM p06_r3_members_f91627529a584d2398b195599b1adb86.runs run USING retained WHERE run.company=retained.company AND run.id=retained.run;
      GET DIAGNOSTICS removed = ROW_COUNT;
      IF removed<>current_setting('p06.review_owned')::bigint THEN
        RAISE EXCEPTION 'review membership changed: locked %, removed %',current_setting('p06.review_owned'),removed;
      END IF;
    END $$;
    COMMIT;

